function renderPreview(){const empty=!state.source;$('.empty-source').hidden=!empty;$('#source-frame').hidden=empty;ctx.clearRect(0,0,1000,1000);ctx.fillStyle='#000';ctx.fillRect(0,0,1000,1000);if(empty)return;sampleCtx.clearRect(0,0,1000,1000);sampleCtx.fillStyle='#000';sampleCtx.fillRect(0,0,1000,1000);const w=sourceImage.naturalWidth||1000,h=sourceImage.naturalHeight||1000,scale=Math.min(1000/w,1000/h);sampleCtx.save();sampleCtx.translate(500,500);sampleCtx.rotate(state.seed*.08);sampleCtx.filter=state.compare?'none':`brightness(${state.brightness+100}%) contrast(${state.contrast+80}%) saturate(${state.saturation}%) blur(${state.softness}px) ${state.invert?'invert(1)':''}`;sampleCtx.drawImage(sourceImage,-w*scale/2,-h*scale/2,w*scale,h*scale);sampleCtx.restore();const mode=currentTile().mode;if(state.compare){ctx.drawImage(sample,0,0);}else if(['characters','ascii','braille','block','dots','mixed','dither','pixel','pixelart'].includes(mode)){ctx.save();ctx.globalAlpha=.16*state.backdrop/100;ctx.filter='blur(6px)';ctx.drawImage(sample,0,0);ctx.restore();const pixels=sampleCtx.getImageData(0,0,1000,1000).data,step=Number(state.size),ramp=state.ramp.split('').reverse().join('')||' .,:;ox%#@';ctx.font=`${step+1}px monospace`;ctx.textBaseline='top';for(let y=0;y<1000;y+=step)for(let x=0;x<1000;x+=step){const i=(y*1000+x)*4,l=(pixels[i]+pixels[i+1]+pixels[i+2])/3;if(l<12)continue;ctx.globalAlpha=state.opacity/100;ctx.globalCompositeOperation={Normal:'source-over',Overlay:'overlay','Color Dodge':'color-dodge',Screen:'screen',Lighter:'lighter'}[state.blend]||'source-over';ctx.fillStyle=`rgb(${pixels[i]},${pixels[i+1]},${pixels[i+2]})`;if(mode==='characters'||mode==='ascii'||mode==='mixed')ctx.fillText(ramp[state.randomize?Math.abs((x*37+y*17+state.seed*13)%ramp.length):Math.min(ramp.length-1,Math.floor(l/256*ramp.length))],x,y);else if(mode==='dots'||mode==='braille'){ctx.beginPath();ctx.arc(x,y,Math.max(.5,l/255*step/2),0,Math.PI*2);ctx.fill();}else if(mode==='dither'){ctx.fillStyle=l>(x%3+y%3)*38?'#eee':'#333';ctx.fillRect(x,y,step*.65,step*.65);}else ctx.fillRect(x,y,step*.85,step*.85);}ctx.restore();}else{ctx.save();ctx.globalAlpha=state.opacity/100;ctx.filter=mode==='cyanotype'||mode==='blueprint'?'sepia(1) saturate(5) hue-rotate(170deg) brightness(1.7)':mode==='crt'?'sepia(.5) saturate(4) hue-rotate(40deg)':mode==='mezzotint'?'contrast(2) sepia(.6)':'none';ctx.drawImage(sample,0,0);ctx.restore();}if(state.dot){ctx.fillStyle='#0008';for(let y=0;y<1000;y+=5)ctx.fillRect(0,y,1000,1);}if(state.coverage<100){ctx.fillStyle=`rgba(0,0,0,${1-state.coverage/100})`;ctx.fillRect(0,0,1000,1000);}$('#text-overlay').textContent=state.text;$('#source-frame').style.transform=`scale(${state.zoom})`;$('#zoom').textContent=Math.round(state.zoom*100)+'%';$('.compare-label').hidden=!state.compare;const fc=$('#flow-preview').getContext('2d');fc.clearRect(0,0,1000,1000);fc.drawImage(preview,0,0);}
