document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.service){showDialog('Not configured',el.dataset.service);return;}if(el.dataset.favorite){const id=el.dataset.favorite;favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem('asciimorph-design-favorites',JSON.stringify([...favorites]));}catch{announce('Favorites could not be saved');}renderCatalog();return;}if(el.dataset.style){selectStyle(el.dataset.style);return;}if(el.dataset.workspace){const flow=el.dataset.workspace==='flow';state.workspace=el.dataset.workspace;document.body.classList.toggle('flow-mode',flow);$('.studio-view').hidden=flow;$('.flow-view').hidden=!flow;$('.studio-actions').hidden=flow;$('.flow-actions').hidden=!flow;$$('[data-workspace]').forEach(b=>{b.classList.toggle('on',b===el);b.setAttribute('aria-pressed',b===el);});syncWorkspaceSegment();renderCatalog();return;}if(el.dataset.tab){state.tab=el.dataset.tab;$$('[data-tab]').forEach(b=>{b.classList.toggle('on',b===el);b.setAttribute('aria-pressed',b===el);});renderCatalog();return;}if(el.dataset.mode){if(state.workspace==='flow')state.flowTab=el.dataset.mode==='generative'?'effects':'styles';else state.mode=el.dataset.mode;syncWorkspaceSegment();renderCatalog();return;}if(el.dataset.panel){state.panel=el.dataset.panel;$$('[data-panel]').forEach(b=>{b.classList.toggle('on',b===el);b.setAttribute('aria-pressed',b===el);});renderProperties();return;}if(el.dataset.library){state.seed=Number(el.dataset.library)*3;state.source=true;thumbnailSrc='assets/botanical.svg?v=20261020-bright';sourceImage=new Image();sourceImage.onload=()=>{renderPreview();renderCatalog();$('.node-source').src=thumbnailSrc;};sourceImage.src=thumbnailSrc;$('#dialog').close();return;}if(el.dataset.recipe){try{const recipe=JSON.parse(localStorage.getItem('asciimorph-design-recipes'))[Number(el.dataset.recipe)];snapshot();Object.assign(state,recipe);renderProperties();renderPreview();announce('Prototype look restored');}catch{}return;}if(el.dataset.action&&actions[el.dataset.action])actions[el.dataset.action]();});
document.addEventListener('input',e=>{const input=e.target;if(input.id==='search'){renderCatalog();return;}if(input.dataset.setting){const key=input.dataset.setting;if(input.type==='range'){state[key]=Number(input.value);input.style.setProperty('--fill',`${(input.value-input.min)/(input.max-input.min)*100}%`);input.previousElementSibling.querySelector('output').textContent=input.value;}else if(input.type==='checkbox')state[key]=input.checked;else if(key==='ramp'){state.ramp=input.value;state.charSet='Custom';}renderPreview();}});
document.addEventListener('pointerdown',e=>{if(e.target.matches('[data-setting]'))snapshot();});
