document.addEventListener('keydown',e=>{if(e.target.matches('[data-setting]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End',' '].includes(e.key))snapshot();if(e.key==='Escape'){closePopovers();document.body.classList.remove('styles-sheet','controls-sheet');}if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!e.target.matches('input,textarea')){e.preventDefault();e.shiftKey?actions.redo():actions.undo();}});
